import puppeteer from '/home/box/.local/lib/node_modules/puppeteer-core/lib/esm/puppeteer/puppeteer-core.js';

const url = 'file://' + process.argv[2];
const viewports = [
  { name: 'desktop', width: 1440, height: 900 },
  { name: 'laptop', width: 1280, height: 800 },
  { name: 'phone', width: 390, height: 844 },
  { name: 'phone-small', width: 360, height: 640 }
];

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/google-chrome',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--allow-file-access-from-files']
});

const page = await browser.newPage();
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });
page.on('pageerror', e => console.log('PAGE ERROR:', e.message));
page.on('requestfailed', r => console.log('REQ FAILED:', r.url().slice(0, 90), r.failure()?.errorText));

for (const vp of viewports) {
  await page.setViewport({ width: vp.width, height: vp.height, deviceScaleFactor: 1 });
  await page.goto(url, { waitUntil: 'networkidle0', timeout: 60000 });
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 700));

  const m = await page.evaluate(() => {
    const out = {};
    const rect = el => { const r = el.getBoundingClientRect(); return { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), right: +r.right.toFixed(1), bottom: +r.bottom.toFixed(1) }; };
    const cs = (el, p) => getComputedStyle(el)[p];

    out.fonts = {
      instrument: document.fonts.check('16px "Instrument Serif"'),
      noto: document.fonts.check('16px "Noto Sans SC"'),
      mono: document.fonts.check('16px "JetBrains Mono"')
    };
    out.gsap = !!(window.gsap && window.ScrollTrigger);
    out.docScrollW = document.documentElement.scrollWidth;
    out.innerW = window.innerWidth;
    out.overflowX = +(document.documentElement.scrollWidth - window.innerWidth).toFixed(1);

    const name = document.querySelector('.hero-name');
    const hero = document.querySelector('.hero');
    out.nameFontSize = cs(name, 'fontSize');
    out.nameRect = rect(name);
    out.heroPadBox = { w: rect(hero).w };
    out.nameOverflowsHero = name.getBoundingClientRect().right > hero.getBoundingClientRect().right + 0.5;

    // baseline vs underline
    const hl = document.querySelector('.hero-name .hl');
    const probe = document.createElement('span');
    probe.style.cssText = 'display:inline-block;width:0;height:0;vertical-align:baseline;';
    hl.appendChild(probe);
    const baseline = probe.getBoundingClientRect().top;
    probe.remove();
    const ul = document.querySelector('.hero-name .ul').getBoundingClientRect();
    out.baseline = +baseline.toFixed(1);
    out.underlineTop = +ul.top.toFixed(1);
    out.underlineOffsetEm = +((ul.top - baseline) / parseFloat(out.nameFontSize)).toFixed(3);
    out.underlineThicknessEm = +((ul.height) / parseFloat(out.nameFontSize)).toFixed(3);
    out.nameFontSizePx = parseFloat(out.nameFontSize);

    // 首屏文案是否在视口内
    const lede = document.querySelector('.lede');
    out.lede = { ...rect(lede), fontSize: cs(lede, 'fontSize'), lineHeight: cs(lede, 'lineHeight'), color: cs(lede, 'color') };
    out.actions = rect(document.querySelector('.actions'));
    out.heroBottomOverflow = +(out.actions.bottom - window.innerHeight).toFixed(1);

    // 页面宽度越界元素
    const bad = [];
    document.querySelectorAll('body *').forEach(el => {
      const r = el.getBoundingClientRect();
      if (r.width && r.right > window.innerWidth + 1) {
        bad.push((el.className && typeof el.className === 'string' ? '.' + el.className.split(' ')[0] : el.tagName) + ' right=' + r.right.toFixed(0));
      }
    });
    out.overflowing = bad.slice(0, 8);

    // 文字角色
    const pick = sel => { const el = document.querySelector(sel); if (!el) return null; const s = getComputedStyle(el); return { size: s.fontSize, lh: s.lineHeight, color: s.color, ff: s.fontFamily.split(',')[0] }; };
    out.type = {
      h2: pick('.sec-head h2'),
      file: pick('.file'),
      aboutP: pick('.about-copy p'),
      rowDesc: pick('.row-desc'),
      rowName: pick('.row-name'),
      role: pick('.role h3'),
      pending: pick('.pending'),
      foot: pick('.foot')
    };
    out.bodyH = document.documentElement.scrollHeight;
    return out;
  });

  // 滚到底，检查所有出场元素是否可见
  await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  await new Promise(r => setTimeout(r, 1600));
  const after = await page.evaluate(() => {
    const hidden = [];
    document.querySelectorAll('[data-reveal],[data-reveal-group] > *').forEach(el => {
      const s = getComputedStyle(el);
      if (parseFloat(s.opacity) < 0.95) hidden.push((el.className || el.tagName) + ' op=' + s.opacity);
    });
    const svg = document.querySelector('#branch-main');
    const side = document.querySelector('#branch-side');
    const t = document.querySelector('#branch-cap');
    return {
      hidden,
      branchMain: svg ? svg.getBoundingClientRect().height : null,
      branchDash: svg ? getComputedStyle(svg).strokeDashoffset : null,
      sideDash: side ? getComputedStyle(side).strokeDashoffset : null,
      branchInView: t ? t.getBoundingClientRect().top : null,
      scrollY: window.scrollY,
      progress: getComputedStyle(document.querySelector('.rail-progress') || document.body).transform
    };
  });

  console.log('\n===== ' + vp.name + ' ' + vp.width + 'x' + vp.height + ' =====');
  console.log(JSON.stringify(m, null, 1));
  console.log('after scroll:', JSON.stringify(after));
}

await browser.close();

