}

edits.newText:
function fitName() {
  if (!nameEl || !nameWrap) return;
  var wrapStyle = getComputedStyle(nameWrap);
  var avail = nameWrap.clientWidth
    - parseFloat(wrapStyle.paddingLeft)
    - parseFloat(wrapStyle.paddingRight);
  if (!avail || avail < 80) return;
  nameEl.style.fontSize = "100px";
  var w = nameEl.getBoundingClientRect().width;
  if (!w) return;
  var size = Math.min(100 * (avail / w) * 0.997, 560);
  nameEl.style.fontSize = size.toFixed(2) + "px";
}

