import puppeteer from '/home/box/.local/lib/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js';
const url = 'file://' + process.argv[2];
const browser = await puppeteer.launch({ executablePath: '/usr/bin/google-chrome', headless: 'new', args: ['--no-sandbox','--allow-file-access-from-files'] });
const page = await browser.newPage();
for (const vp of [{n:'desktop',w:1440,h:900},{n:'phone',w:390,h:844}]) {
  await page.setViewport({width:vp.w,height:vp.h});
  await page.goto(url,{waitUntil:'networkidle0'});
  await page.evaluate(()=>document.fonts.ready);
  await new Promise(r=>setTimeout(r,1600));
  const res = await page.evaluate(() => {
    const r = el => el.getBoundingClientRect();
    const out = { sections: [], overlaps: [], gaps: [] };
    document.querySelectorAll('main > section').forEach(s => {
      out.sections.push({
        id: s.id || s.className, top: Math.round(r(s).top + scrollY), h: Math.round(r(s).height),
        bg: getComputedStyle(s).backgroundColor
      });
    });
    // 主要文本块的字号/行数抽样
    const lines = sel => document.querySelectorAll(sel).length;
    out.counts = {
      rows: document.querySelectorAll('.row').length,
      ext: document.querySelectorAll('.ext li').length,
      h2: lines('.sec-head h2')
    };
    // 检查每个 section 内部元素互相重叠（同层文字块）
    const key = document.querySelectorAll('.lede, .actions, .hero-aside, .hero-name, .about-copy, .portrait, .facts, .flagship-copy, .branch, .stack, .now, .roles, .ext, .sticker, .foot');
    const arr = [...key].map(el => ({ el: el.className || el.tagName, ...(() => { const b = r(el); return { t: Math.round(b.top), b: Math.round(b.bottom), l: Math.round(b.left), rr: Math.round(b.right) }; })() }));
    for (let i=0;i<arr.length;i++) for (let j=i+1;j<arr.length;j++) {
      const a=arr[i], c=arr[j];
      const ox = Math.min(a.rr,c.rr)-Math.max(a.l,c.l);
      const oy = Math.min(a.b,c.b)-Math.max(a.t,c.t);
      if (ox>4 && oy>4) out.overlaps.push(`${a.el} × ${c.el} (${ox}x${oy})`);
    }
    // 弱检查：文案是否被裁切
    document.querySelectorAll('h1,h2,h3,p,dd,figcaption,.row-desc').forEach(el => {
      if (el.scrollWidth > el.clientWidth + 2 && getComputedStyle(el).overflow !== 'visible') out.gaps.push('clipped:' + (el.className||el.tagName));
    });
    out.heroName = { w: Math.round(r(document.querySelector('.hero-name')).width), h: Math.round(r(document.querySelector('.hero-name')).height) };
    out.branchSvg = (() => { const b = r(document.querySelector('.branch svg')); return { w: Math.round(b.width), h: Math.round(b.height) }; })();
    out.stickerImg = (() => { const b = r(document.querySelector('.sticker img')); return { w: Math.round(b.width), h: Math.round(b.height) }; })();
    out.portraitImg = (() => { const b = r(document.querySelector('.portrait img')); return { w: Math.round(b.width), h: Math.round(b.height) }; })();
    out.docH = document.documentElement.scrollHeight;
    return out;
  });
  console.log('\n=== ' + vp.n + ' ===');
  console.log(JSON.stringify(res, null, 1));
}
await browser.close();
