  await new Promise(r=>setTimeout(r,1200));
  const res=await page.evaluate(()=>{
    const rects=[];
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
    let n;
    while((n=walker.nextNode())){
      if(!n.textContent.trim()) continue;
      const p=n.parentElement;
      if(!p || p.closest('.sr')) continue;
      const cs=getComputedStyle(p);
      if(cs.opacity==='0'||cs.visibility==='hidden'||cs.display==='none') continue;
      const r=document.createRange(); r.selectNodeContents(n);
      for(const b of r.getClientRects()){
        if(b.width<2||b.height<2) continue;
        rects.push({t:n.textContent.trim().slice(0,18), p:(p.className&&typeof p.className==='string'?'.'+p.className.split(' ')[0]:p.tagName), x:+b.x.toFixed(1),y:+b.y.toFixed(1),w:+b.width.toFixed(1),h:+b.height.toFixed(1)});
      }
    }
    const hits=[];
    for(let i=0;i<rects.length;i++)for(let j=i+1;j<rects.length;j++){
      const a=rects[i],c=rects[j];
      if(a.p===c.p&&Math.abs(a.y-c.y)<2) continue; // 同一行内联
      const ox=Math.min(a.x+a.w,c.x+c.w)-Math.max(a.x,c.x);
      const oy=Math.min(a.y+a.h,c.y+c.h)-Math.max(a.y,c.y);
      if(ox>3&&oy>3){
        const area=ox*oy; const small=Math.min(a.w*a.h,c.w*c.h);
        if(area/small>0.3) hits.push(`${a.p}「${a.t}」×${c.p}「${c.t}」 ${ox.toFixed(0)}x${oy.toFixed(0)}`);
      }
    }
    // 越界文字
    const out=[];
    const W=innerWidth;
    rects.forEach(r=>{ if(r.x<-1||r.x+r.w>W+1) out.push(`${r.p}「${r.t}」x=${r.x} w=${r.w}`); });
    return {count:rects.length, hits:[...new Set(hits)].slice(0,20), outside:[...new Set(out)].slice(0,10)};
  });
  console.log('\n==',vp.n,'text rects',res.count);
  console.log('overlaps:',res.hits.length?res.hits:'none');
  console.log('outside viewport:',res.outside.length?res.outside:'none');
}
await browser.close();
EOF
