from html.parser import HTMLParser
VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.errs=[]
    def handle_starttag(self,tag,attrs):
        if tag not in VOID: self.stack.append((tag,self.getpos()))
    def handle_endtag(self,tag):
        if not self.stack: self.errs.append(('extra close',tag,self.getpos())); return
        if self.stack[-1][0]!=tag:
            self.errs.append(('mismatch',self.stack[-1],tag,self.getpos()))
            # try to recover
            for i in range(len(self.stack)-1,-1,-1):
                if self.stack[i][0]==tag: del self.stack[i:]; return
        else: self.stack.pop()
p=P(); p.feed(open('index.html',encoding='utf-8').read())
print('errors:',p.errs[:5]); print('unclosed:',[s for s in p.stack][:5])
EOF

